class Solution {
public:
    vector<int> lastVisitedIntegers(vector<int>& nums) {
        vector<int> seen, answer;
        int consecutive = 0;
        for (int x : nums) {
            if (x != -1) {
                seen.push_back(x);
                consecutive = 0;
            } else {
                ++consecutive;
                int size = seen.size();
                answer.push_back(consecutive <= size ? seen[size - consecutive] : -1);
            }
        }
        return answer;
    }
};
